declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';header('Content-Type: application/json; charset=utf-8');function fail_json(string $m,int $s=400):never{http_response_code($s);echo json_encode(['message'=>$m],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}if($_SERVER['REQUEST_METHOD']!=='POST')fail_json('Method not allowed',405);try{$token=(string)($_POST['csrf']??'');if($token===''||!hash_equals((string)($_SESSION['csrf']??''),$token))fail_json('เซสชันหมดอายุ กรุณาเปิดหน้าใหม่',419);if(($_POST['consent']??'')!=='1')fail_json('กรุณายอมรับการประมวลผลใบหน้า');$eventId=filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT id,face_threshold FROM events WHERE id=? AND is_active=1 LIMIT 1');$s->execute([$eventId]);$event=$s->fetch();if(!$event)fail_json('ไม่พบกิจกรรม',404);if(!isset($_FILES['selfie'])||$_FILES['selfie']['error']!==UPLOAD_ERR_OK)fail_json('กรุณาเลือกรูปใบหน้า');if((int)$_FILES['selfie']['size']>MAX_UPLOAD_BYTES)fail_json('ไฟล์ใหญ่เกินกำหนด');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['selfie']['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))fail_json('รองรับเฉพาะ JPG, PNG และ WebP');$post=['event_id'=>(string)$eventId,'threshold'=>(string)$event['face_threshold'],'selfie'=>new CURLFile($_FILES['selfie']['tmp_name'],$mime,'selfie.'.$allowed[$mime])];$c=curl_init(rtrim(FACE_SERVICE_URL,'/').'/search');curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$post,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['X-Service-Token: '.FACE_SERVICE_TOKEN],CURLOPT_TIMEOUT=>180]);$body=curl_exec($c);$status=(int)curl_getinfo($c,CURLINFO_RESPONSE_CODE);$error=curl_error($c);curl_close($c);if($body===false||$status>=400){$decoded=is_string($body)?json_decode($body,true):null;fail_json(is_array($decoded)?(string)($decoded['message']??'Face Service ไม่พร้อม'):($error?:'Face Service ไม่พร้อม'),503);}$matches=json_decode((string)$body,true